-- ReviewGrowth AI initial multi-tenant schema.
create extension if not exists pgcrypto;
create type public.business_member_role as enum ('owner', 'admin', 'manager', 'staff');
create type public.feedback_status as enum ('new', 'needs_attention', 'in_progress', 'resolved', 'archived');
create type public.feedback_source as enum ('qr', 'web', 'manual');
create type public.subscription_status as enum ('trialing', 'active', 'past_due', 'cancelled', 'incomplete');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.businesses (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, category text not null, website_url text, timezone text not null default 'Asia/Kolkata', created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.business_members (business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.business_member_role not null default 'staff', created_at timestamptz not null default now(), primary key (business_id, user_id));
create table public.locations (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, address text, city text, state text, postal_code text, public_slug text not null unique, google_place_id text, google_location_name text, google_review_url text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (id, business_id));
create table public.feedback (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, rating smallint not null check (rating between 1 and 5), message text not null check (char_length(message) between 8 and 3000), customer_name text, customer_email text, source public.feedback_source not null default 'qr', status public.feedback_status not null default 'new', assigned_to uuid references auth.users(id) on delete set null, resolution_note text, resolved_at timestamptz, created_at timestamptz not null default now(), constraint feedback_location_business_match foreign key (location_id, business_id) references public.locations(id, business_id) deferrable initially deferred);
create table public.ai_review_drafts (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, location_id uuid references public.locations(id) on delete set null, feedback_id uuid references public.feedback(id) on delete set null, language text not null default 'English', source_experience text not null, draft_text text not null, customer_approved boolean not null default false, created_at timestamptz not null default now());
create table public.google_connections (id uuid primary key default gen_random_uuid(), business_id uuid not null unique references public.businesses(id) on delete cascade, google_account_id text, access_token_encrypted text, refresh_token_encrypted text, token_expires_at timestamptz, scopes text[] not null default '{}', connected_by uuid references auth.users(id), connected_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.google_reviews (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, location_id uuid references public.locations(id) on delete set null, google_review_id text not null, reviewer_name text, star_rating smallint check (star_rating between 1 and 5), review_text text, review_created_at timestamptz, owner_reply text, owner_reply_updated_at timestamptz, synced_at timestamptz not null default now(), unique (business_id, google_review_id));
create table public.subscriptions (id uuid primary key default gen_random_uuid(), business_id uuid not null unique references public.businesses(id) on delete cascade, plan_code text not null default 'starter', status public.subscription_status not null default 'trialing', billing_provider text, provider_customer_id text, provider_subscription_id text, current_period_start timestamptz, current_period_end timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notification_preferences (business_id uuid primary key references public.businesses(id) on delete cascade, alert_email text, alert_phone text, email_enabled boolean not null default true, whatsapp_enabled boolean not null default false, negative_feedback_alert boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index feedback_business_created_idx on public.feedback (business_id, created_at desc);
create index feedback_location_created_idx on public.feedback (location_id, created_at desc);
create index feedback_attention_idx on public.feedback (business_id, status, created_at desc);
create index google_reviews_business_created_idx on public.google_reviews (business_id, review_created_at desc);
create or replace function public.is_business_member(target_business_id uuid) returns boolean language sql stable security invoker set search_path = '' as $$ select exists (select 1 from public.business_members bm where bm.business_id = target_business_id and bm.user_id = (select auth.uid())); $$;
create or replace function public.has_business_role(target_business_id uuid, allowed_roles public.business_member_role[]) returns boolean language sql stable security invoker set search_path = '' as $$ select exists (select 1 from public.business_members bm where bm.business_id = target_business_id and bm.user_id = (select auth.uid()) and bm.role = any(allowed_roles)); $$;
alter table public.profiles enable row level security;
alter table public.businesses enable row level security;
alter table public.business_members enable row level security;
alter table public.locations enable row level security;
alter table public.feedback enable row level security;
alter table public.ai_review_drafts enable row level security;
alter table public.google_connections enable row level security;
alter table public.google_reviews enable row level security;
alter table public.subscriptions enable row level security;
alter table public.notification_preferences enable row level security;
create policy "Users can read own profile" on public.profiles for select to authenticated using (id = (select auth.uid()));
create policy "Users can update own profile" on public.profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy "Business members can read their businesses" on public.businesses for select to authenticated using (public.is_business_member(id));
create policy "Creators can read their own businesses before membership setup" on public.businesses for select to authenticated using (created_by = (select auth.uid()));
create policy "Authenticated users can create a business" on public.businesses for insert to authenticated with check (created_by = (select auth.uid()));
create policy "Business admins can update their business" on public.businesses for update to authenticated using (public.has_business_role(id, array['owner','admin']::public.business_member_role[])) with check (public.has_business_role(id, array['owner','admin']::public.business_member_role[]));
create policy "Users can read their own membership rows" on public.business_members for select to authenticated using (user_id = (select auth.uid()));
create policy "Owners and admins can add business members" on public.business_members for insert to authenticated with check (public.has_business_role(business_id, array['owner','admin']::public.business_member_role[]));
create policy "Business creator can claim initial owner role" on public.business_members for insert to authenticated with check (user_id = (select auth.uid()) and role = 'owner' and exists (select 1 from public.businesses b where b.id = business_id and b.created_by = (select auth.uid())));
create policy "Members can read locations" on public.locations for select to authenticated using (public.is_business_member(business_id));
create policy "Public can resolve active feedback locations" on public.locations for select to anon using (is_active = true);
create policy "Admins can manage locations" on public.locations for all to authenticated using (public.has_business_role(business_id, array['owner','admin','manager']::public.business_member_role[])) with check (public.has_business_role(business_id, array['owner','admin','manager']::public.business_member_role[]));
create policy "Members can read feedback" on public.feedback for select to authenticated using (public.is_business_member(business_id));
create policy "Public can submit feedback to active locations" on public.feedback for insert to anon, authenticated with check (exists (select 1 from public.locations l where l.id = feedback.location_id and l.business_id = feedback.business_id and l.is_active = true));
create policy "Managers can update feedback" on public.feedback for update to authenticated using (public.has_business_role(business_id, array['owner','admin','manager']::public.business_member_role[])) with check (public.has_business_role(business_id, array['owner','admin','manager']::public.business_member_role[]));
create policy "Members can read AI drafts" on public.ai_review_drafts for select to authenticated using (public.is_business_member(business_id));
create policy "Members can create AI drafts" on public.ai_review_drafts for insert to authenticated with check (public.is_business_member(business_id));
create policy "Members can read Google reviews" on public.google_reviews for select to authenticated using (public.is_business_member(business_id));
create policy "Members can read subscription" on public.subscriptions for select to authenticated using (public.is_business_member(business_id));
create policy "Owners can manage notification preferences" on public.notification_preferences for all to authenticated using (public.has_business_role(business_id, array['owner','admin']::public.business_member_role[])) with check (public.has_business_role(business_id, array['owner','admin']::public.business_member_role[]));
grant select (id, business_id, public_slug, is_active, google_review_url) on public.locations to anon, authenticated;
grant insert (business_id, location_id, rating, message, customer_name, customer_email, source, status) on public.feedback to anon, authenticated;
grant select, insert, update on public.feedback to authenticated;
grant select on public.businesses to authenticated;
grant select, insert, update on public.locations to authenticated;
grant select, insert, update, delete on public.business_members to authenticated;
grant select, insert, update on public.ai_review_drafts to authenticated;
grant select on public.google_reviews to authenticated;
grant select on public.subscriptions to authenticated;
grant select, insert, update on public.notification_preferences to authenticated;
